                if lis[j] + 1 > lis[i]:
                    lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each position
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i]:
                if lds[j] + 1 > lds[i]:
                    lds[i] = lds[j] + 1

    # Combine to find the longest bitonic subsequence
    max_len = 0
    for i in range(n):
        current = lis[i] + lds[i] - 1
        if current > max_len:
            max_len = current

    return n - max_len

def total_smoked_cigarettes(n, k):
    if k <= 1:
        return n
    total = n
    butts = n
    while butts >= k:
        new = butts // k
        total += new
        butts = new + (butts % k)
    return total
